        broadcastToRoom(currentRoom, {
          type: 'presence',
          event: 'leave',
          peerId,
          peerCount: set.size
        });
      }
      currentRoom = null;
    }
  };

  ws.on('close', cleanup);
  ws.on('error', cleanup);
});

