  }

  .dock-btn svg {
    width: 15px;
    height: 15px;
  }

  .fingerprint-btn {
    padding: 0 6px;
    height: 34px;
  }

  .fp-mini-text {
    font-size: 0.72rem;
    letter-spacing: 1px;
  }

  .panic-btn-mini {
    padding: 6px 10px;
    font-size: 0.72rem;
    gap: 4px;
