  }

  .lobby-shield-icon {
    width: 46px;
    height: 46px;
    border-radius: 14px;
    margin-bottom: 10px;
  }

  .lobby-shield-icon svg {
    width: 22px;
    height: 22px;
  }

  .lobby-header-clean h2 {
    font-size: 1.45rem;
  }

