    font-size: 0.75rem;
  }

  .form-group {
    margin-bottom: 16px;
  }

  .form-label {
    font-size: 0.82rem;
    margin-bottom: 6px;
  }

  .label-action {
    font-size: 0.8rem;
    padding: 2px 4px;
  }

