  .input-field {
    font-size: 16px !important;
    padding: 12px 14px;
    min-height: 48px;
    border-radius: 10px;
  }

  .input-addon-btn {
    min-height: 34px;
    padding: 6px 10px;
    font-size: 0.8rem;
    right: 6px;
  }

  .join-btn {
    min-height: 52px;
    font-size: 1.05rem;
    border-radius: 12px;
    margin-top: 4px;
  }

  /* Chat Screen on Mobile */
  .channel-start-pill {
    font-size: 0.68rem;
    padding: 6px 12px;
    margin: 10px auto;
    text-align: center;
    max-width: 95%;
  }

  .messages-viewport {
    padding: 12px 10px;
    gap: 12px;
  }

  .msg-row {
    max-width: 88%;
  }

  .msg-bubble {
    padding: 10px 14px;
    font-size: 0.94rem;
    border-radius: 14px;
  }

  .msg-meta {
    font-size: 0.68rem;
    gap: 6px;
  }

  .chat-input-area {
    padding: 8px 10px max(10px, env(safe-area-inset-bottom, 0px)) 10px;
