      </button>
    </div>
  `;

  const replyBtn = row.querySelector('.msg-reply-btn');
  if (replyBtn) {
    replyBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      startReplyingTo({
        sender: sender,
        text: text || (image ? 'Photo' : 'Encrypted message')
      });
    });
  }

