// Initialize Local Camera & Microphone with Resilient Fallback
const startMedia = async () => {
  if (localStream) {
    localStream.getTracks().forEach(t => t.stop());
    localStream = null;
  }

  const isMobile = /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);

  // Tier 1: Preferred High Quality Video + Audio
  try {
    const videoConstraints = isMobile
      ? { facingMode: facingMode, width: { ideal: 1280 }, height: { ideal: 720 } }
      : { width: { ideal: 1280 }, height: { ideal: 720 } };

    localStream = await navigator.mediaDevices.getUserMedia({
      audio: { echoCancellation: true, noiseSuppression: true },
      video: videoConstraints
    });
    localVideo.srcObject = localStream;
    isVideoOff = false;
    btnToggleVideo.classList.remove('off');
    iconVideoOn.style.display = 'block';
    iconVideoOff.style.display = 'none';
    return true;
  } catch (e1) {
    console.warn('Preferred video constraints failed, trying basic video...', e1);
  }

  // Tier 2: Basic Video + Audio (relaxed constraints)
  try {
    localStream = await navigator.mediaDevices.getUserMedia({
      audio: true,
      video: true
    });
    localVideo.srcObject = localStream;
    isVideoOff = false;
    btnToggleVideo.classList.remove('off');
    iconVideoOn.style.display = 'block';
    iconVideoOff.style.display = 'none';
