// Controls: Toggle Video
btnToggleVideo.addEventListener('click', async () => {
  if (!localStream) return;
  const videoTracks = localStream.getVideoTracks();
  if (videoTracks.length === 0) {
    // If started as audio-only, try acquiring video track
    try {
      const vStream = await navigator.mediaDevices.getUserMedia({ video: true });
      const vTrack = vStream.getVideoTracks()[0];
      localStream.addTrack(vTrack);
      localVideo.srcObject = localStream;
      if (peerConnection) {
        peerConnection.addTrack(vTrack, localStream);
        createAndSendOffer();
      }
      isVideoOff = false;
      btnToggleVideo.classList.remove('off');
      iconVideoOn.style.display = 'block';
      iconVideoOff.style.display = 'none';
      showToast('📹 Camera activated');
      return;
    } catch (e) {
      showToast('⚠️ Could not start camera: ' + (e.message || 'Camera busy'));
      return;
    }
  }
  isVideoOff = !isVideoOff;
  videoTracks.forEach(t => t.enabled = !isVideoOff);
  btnToggleVideo.classList.toggle('off', isVideoOff);
  iconVideoOn.style.display = isVideoOff ? 'none' : 'block';
  iconVideoOff.style.display = isVideoOff ? 'block' : 'none';
  showToast(isVideoOff ? 'Camera Off' : 'Camera On');
});

