args.CodeContent:
const fs = require('fs');
const html = fs.readFileSync('public/index.html', 'utf8');
const js = fs.readFileSync('public/app.js', 'utf8');

const regex = /document\.getElementById\(['"]([^'"]+)['"]\)/g;
let match;
const missing = [];
while ((match = regex.exec(js)) !== null) {
  const id = match[1];
  if (!html.includes(`id="${id}"`) && !html.includes(`id='${id}'`)) {
    missing.push(id);
  }
}
console.log('Missing IDs:', [...new Set(missing)]);

const fs = require('fs');
const js = fs.readFileSync('public/app.js', 'utf8');

const missing = [
  'cryptoStatusLabel',
  'statusDot',
  'headerSymbolDock',
  'roomDockBtn',
  'peerDockBtn',
  'chaffStatusBadge',
  'safetyFingerprintBadge',
  'safetyFingerprintCode',
  'cryptoIndicator',
  'localIpContainer',
  'shieldIndicator',
  'shieldLabel'
];

for (const id of missing) {
  const lines = js.split('\n');
  lines.forEach((line, idx) => {
    if (line.includes(id)) {
      console.log(`${id} at line ${idx + 1}: ${line.trim()}`);
    }
  });
}

