const fs = require('fs');
const js = fs.readFileSync('public/app.js', 'utf8');

// Find all const/let declarations with getElementById
const declRegex = /(?:const|let)\s+([a-zA-Z0-9_$]+)\s*=\s*document\.getElementById\(['"]([^'"]+)['"]\)/g;
let m;
const declaredVars = [];
while ((m = declRegex.exec(js)) !== null) {
  declaredVars.push({ varName: m[1], id: m[2] });
}

console.log(`Found ${declaredVars.length} element variables.`);

const html = fs.readFileSync('public/index.html', 'utf8');

const missingVars = declaredVars.filter(v => !html.includes(`id="${v.id}"`) && !html.includes(`id='${v.id}'`));
console.log('Missing from HTML:', missingVars.map(v => v.varName));

// For each missing var, check if it's accessed without `if (varName)`
for (const item of missingVars) {
  const v = item.varName;
  const lines = js.split('\n');
  lines.forEach((line, i) => {
    // If line mentions v followed by .something and line does not start with if (v
    const regex = new RegExp(`\\b${v}\\.[a-zA-Z0-9_$]+`);
    if (regex.test(line) && !line.includes(`if (${v})`) && !line.includes(`if (!${v})`) && !line.includes(`${v} ?`) && !line.includes(`${v} &&`)) {
      console.log(`POTENTIAL UNGUARDED ACCESS: Line ${i + 1}: ${line.trim()}`);
    }
  });
}

