/* ==========================================================================
   ACTIVE PEERS MODAL & CHAT HEADER DETAILS
   ========================================================================== */
.chat-header-info {
  display: flex;
  align-items: center;
  gap: 12px;
}

.header-back-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 9px;
  color: #94a3b8;
  cursor: pointer;
  transition: all 0.15s ease;
}

.header-back-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
}

.chat-title-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.chat-room-title {
  font-family: var(--font-mono);
  font-size: 0.88rem;
  font-weight: 700;
  color: #f1f5f9;
  letter-spacing: -0.01em;
}

.chat-peer-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(16, 185, 129, 0.12);
  border: 1px solid rgba(16, 185, 129, 0.3);
  color: #34d399;
  font-size: 0.72rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
  width: fit-content;
}

.chat-peer-btn:hover {
  background: rgba(16, 185, 129, 0.22);
  border-color: #34d399;
}

.status-indicator-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #10b981;
  box-shadow: 0 0 6px #10b981;
}

/* Active Peers Modal */
.peers-modal {
  position: fixed;
  inset: 0;
  z-index: 999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.peers-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(3, 7, 18, 0.8);
  backdrop-filter: blur(8px);
}

.peers-dialog {
  position: relative;
  z-index: 1000;
  width: 100%;
  max-width: 380px;
  background: rgba(15, 23, 42, 0.95);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.7);
  animation: modalFadePop 0.2s ease-out;
}

@keyframes modalFadePop {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

.peers-dialog-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.peers-header-left {
  display: flex;
  align-items: center;
  gap: 8px;
}

.peers-header-left h4 {
  font-family: var(--font-display, inherit);
  font-size: 0.95rem;
  font-weight: 700;
  color: #f8fafc;
  margin: 0;
}

.peers-list-container {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 280px;
  overflow-y: auto;
}

.peer-item-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 10px;
}

.peer-name-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.88rem;
  color: #f1f5f9;
}

.peer-badge-you {
  font-size: 0.68rem;
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 999px;
  background: rgba(16, 185, 129, 0.18);
  border: 1px solid rgba(16, 185, 129, 0.4);
  color: #34d399;
  letter-spacing: 0.05em;
}

/* ==========================================================================
   MOBILE & TOUCH OPTIMIZATIONS
   ========================================================================== */

