const fs = require('fs');
const path = require('path');

const issues = [];

// 1. Check for persistence leaks (localStorage, indexedDB, cookies)
const clientFiles = ['public/app.js', 'public/crypto.js', 'public/video/index.html', 'public/index.html'];
for (const file of clientFiles) {
  const content = fs.readFileSync(file, 'utf8');
  if (content.includes('localStorage')) {
    issues.push(`[PERSISTENCE WARNING] ${file} contains localStorage!`);
  }
  if (content.includes('indexedDB')) {
    issues.push(`[PERSISTENCE WARNING] ${file} contains indexedDB!`);
  }
  if (content.includes('document.cookie')) {
    issues.push(`[PERSISTENCE WARNING] ${file} contains document.cookie!`);
  }
}

// 2. Check for sensitive logging (passphrase, key, plaintext)
for (const file of clientFiles) {
  const lines = fs.readFileSync(file, 'utf8').split('\n');
  lines.forEach((line, i) => {
    if (line.includes('console.log') || line.includes('console.info')) {
      if (line.toLowerCase().includes('passphrase') || line.toLowerCase().includes('secretkey') || line.toLowerCase().includes('derivedkey') || line.toLowerCase().includes('plaintext')) {
        issues.push(`[LOG LEAK WARNING] ${file}:${i+1}: ${line.trim()}`);
      }
    }
  });
}

// 3. Check for DOM ID mismatches in public/app.js
const appHtml = fs.readFileSync('public/index.html', 'utf8');
const appJs = fs.readFileSync('public/app.js', 'utf8');

const idRegex = /(?:const|let)\s+([a-zA-Z0-9_$]+)\s*=\s*document\.getElementById\(['"]([^'"]+)['"]\)/g;
let m;
while ((m = idRegex.exec(appJs)) !== null) {
  const varName = m[1];
  const id = m[2];
  if (!appHtml.includes(`id="${id}"`) && !appHtml.includes(`id='${id}'`)) {
    // Check if varName is used without guard
    const lines = appJs.split('\n');
    lines.forEach((line, lineNum) => {
      const reg = new RegExp(`\\b${varName}\\.[a-zA-Z0-9_$]+`);
      if (reg.test(line) && !line.includes(`if (${varName})`) && !line.includes(`if (!${varName})`) && !line.includes(`${varName} ?`) && !line.includes(`${varName} &&`)) {
        issues.push(`[UNGUARDED DOM ACCESS] public/app.js:${lineNum+1} accesses missing ID "${id}" via variable ${varName}: ${line.trim()}`);
      }
    });
  }
}

// 4. Check for DOM ID mismatches in public/video/index.html
const videoHtml = fs.readFileSync('public/video/index.html', 'utf8');
const videoIdRegex = /(?:const|let)\s+([a-zA-Z0-9_$]+)\s*=\s*document\.getElementById\(['"]([^'"]+)['"]\)/g;
while ((m = videoIdRegex.exec(videoHtml)) !== null) {
  const varName = m[1];
  const id = m[2];
  if (!videoHtml.includes(`id="${id}"`) && !videoHtml.includes(`id='${id}'`)) {
    issues.push(`[MISSING VIDEO DOM ID] public/video/index.html: missing element #${id} declared as ${varName}`);
  }
}

// 5. Check server.js security
const serverJs = fs.readFileSync('server.js', 'utf8');
if (!serverJs.includes('filePath.startsWith(PUBLIC_DIR)')) {
  issues.push('[SERVER SECURITY WARNING] Path traversal check missing in server.js');
}

console.log('=== AUDIT RESULTS ===');
if (issues.length === 0) {
  console.log('ALL CHECKS PASSED: Zero persistence leaks, zero log leaks, zero unguarded DOM IDs, path traversal protected.');
} else {
  issues.forEach(iss => console.log(iss));
}

